const PASSION_READINGS: Record<string, string> = {
  Volcanic: "You two can't share a room without it turning into something. The pull hits before logic does, which is why your fights and your make-ups blur together. The trap: mistaking heat for resolution. The move: finish the argument before you touch.",
  High: "The spark didn't burn out after the first months, and both of you know it. Touch is how you settle things, check in and say sorry without words. The trap: letting chemistry cover for conversations you keep skipping. The move: say the hard sentence first, then reach for each other.",
  Moderate: "Desire between you two builds with trust instead of hitting on sight. The heat shows up once you both feel safe, and it stalls the moment one of you feels rushed or judged. The trap: deciding the spark is missing when it's just waiting. The move: make time that has no agenda except each other.",
  Low: "Attraction isn't the glue here; respect, humor or loyalty is. You two have to build chemistry on purpose instead of waiting for it to strike. The trap: quietly comparing this to a past fling that burned hot. The move: plan the date, the trip, the night, and treat desire as something you practice.",
};

const MARRIAGE_READINGS: Record<string, string> = {
  Exceptional: "This is the kind of bond people build a whole life on: shared home, shared money, shared plans ten years out. It feels so settled that the danger is coasting. The move: keep choosing each other out loud, especially when it's boring.",
  Strong: "You two handle the unglamorous parts well: bills, chores, showing up when nothing exciting is happening. That's what long-term actually runs on. The trap: becoming great roommates and forgetting to flirt.",
  Promising: "The foundation is there, but it only holds with agreements said out loud: money, space, whose family gets the holidays. Leave those unspoken and resentment fills the gaps.",
  Possible: "Commitment works for you two only if you design it on your own terms. Copying the standard script (same house, same timeline as everyone else) will chafe. Write your own rules and revisit them every year.",
  Unlikely: "This connection is built for intensity or growth more than a quiet shared mortgage. If forever is what you want, you'll have to build the structure deliberately, because it won't form on its own.",
};

const BODY_ALIASES: Record<string, string> = {
  ASC: 'Ascendant', Rising: 'Ascendant', DSC: 'Descendant', Midheaven: 'MC', 'True Node': 'North Node', 'Mean Node': 'North Node',
};

function body(name: string): string {
  return BODY_ALIASES[name] || name;
}

/** Reading for a synastry pair, or null when that pair has none written. */
export function getSynastryPairReading(planet1: string, planet2: string, supportive: boolean): string | null {
  const entry = PAIR_READINGS[[body(planet1), body(planet2)].sort().join('-')];
  if (!entry) return null;
  return supportive ? entry.supportive : entry.challenging;
}

export function getPassionReading(intensity: string | null | undefined): string | null {
  return (intensity && PASSION_READINGS[intensity]) || null;
}

export function getMarriageReading(level: string | null | undefined): string | null {
  return (level && MARRIAGE_READINGS[level]) || null;
}
